package com.hbm.client.reactor.rbmk.crane;
import com.hbm.client.model.*;
import com.hbm.machine.reactor.rbmk.crane.RbmkCraneEntity;
import com.hbm.multiblock.DummyableBlock;
import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.math.Axis;
import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.*;
import net.minecraft.client.renderer.blockentity.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.phys.AABB;
/** Complete original Console_Coonsole/JoyStick/Meters/Lamps and procedural Girder/Main/Tube/Carriage/Lift authored models. */
public final class RbmkCraneRenderer implements BlockEntityRenderer<RbmkCraneEntity> {
    private static final ResourceLocation CONSOLE=ResourceLocation.parse("hbm:models/rbmk/crane_console.obj"),CRANE=ResourceLocation.parse("hbm:models/rbmk/crane.obj"),CONSOLE_TEXTURE=ResourceLocation.parse("hbm:textures/models/machines/crane_console.png"),CRANE_TEXTURE=ResourceLocation.parse("hbm:textures/models/machines/rbmk_crane.png");
    public RbmkCraneRenderer(BlockEntityRendererProvider.Context context){}
    private static WavefrontMesh model(ResourceLocation model){return LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),model);}
    private static void part(ResourceLocation model,ResourceLocation texture,String group,PoseStack poses,MultiBufferSource buffers,int light,int overlay){LegacyObjRenderer.render(model(model),poses,buffers.getBuffer(RenderType.entityCutoutNoCull(texture)),light,overlay,-1,LegacyObjRenderer.Convention.HFR,face->face.legacyPart().equals(group));}
    private static void console(String group,PoseStack poses,MultiBufferSource buffers,int light,int overlay){part(CONSOLE,CONSOLE_TEXTURE,group,poses,buffers,light,overlay);}private static void crane(String group,PoseStack poses,MultiBufferSource buffers,int light,int overlay){part(CRANE,CRANE_TEXTURE,group,poses,buffers,light,overlay);}
    private static void lamp(String group,int color,PoseStack poses,MultiBufferSource buffers,int overlay){LegacyObjRenderer.render(model(CONSOLE),poses,buffers.getBuffer(RbmkCraneRenderTypes.LAMPS),LightTexture.FULL_BRIGHT,overlay,color,LegacyObjRenderer.Convention.HFR,face->face.legacyPart().equals(group));}
    @Override public void render(RbmkCraneEntity machine,float partial,PoseStack poses,MultiBufferSource buffers,int light,int overlay){float angle=switch(DummyableBlock.facing(machine.getBlockState())){case NORTH->90;case WEST->180;case SOUTH->270;default->0;};var transform=new org.joml.Matrix4f().translation(.5F,0,.5F).rotateY((float)Math.toRadians(angle)).translate(.5F,0,0);LegacyContactShadows.render(machine,model(CONSOLE),transform,poses,buffers);poses.pushPose();poses.translate(.5,0,.5);poses.mulPose(Axis.YP.rotationDegrees(angle));poses.translate(.5,0,0);console("Console_Coonsole",poses,buffers,light,overlay);
        poses.pushPose();poses.translate(.75,1,0);poses.mulPose(Axis.ZP.rotationDegrees((float)(machine.lastTiltFront+(machine.tiltFront-machine.lastTiltFront)*partial)));poses.mulPose(Axis.XP.rotationDegrees((float)(machine.lastTiltLeft+(machine.tiltLeft-machine.lastTiltLeft)*partial)));poses.translate(-.75,-1.015,0);console("JoyStick",poses,buffers,light,overlay);poses.popPose();
        poses.pushPose();poses.translate(0,1.25,.75);double jitter=Math.sin(System.currentTimeMillis()*.01%360)*180/Math.PI*.05;poses.mulPose(Axis.XP.rotationDegrees((float)(jitter+135-270*machine.loadedHeat)));poses.translate(0,-1.25,-.75);console("Meter1",poses,buffers,light,overlay);poses.popPose();poses.pushPose();poses.translate(0,1.25,.25);poses.mulPose(Axis.XP.rotationDegrees((float)(jitter+135-270*machine.loadedEnrichment)));poses.translate(0,-1.25,-.25);console("Meter2",poses,buffers,light,overlay);poses.popPose();
        lamp("Lamp1",machine.isCraneLoading()?0xffcccc00:machine.hasItemLoaded()?0xff00ff00:0xff001900,poses,buffers,overlay);lamp("Lamp2",machine.isAboveValidTarget()?0xff00ff00:0xffff0000,poses,buffers,overlay);poses.popPose();
        if(!machine.setUpCrane)return;poses.pushPose();var p=machine.getBlockPos();poses.translate(.5+machine.centerX-p.getX(),machine.centerY-p.getY(),.5+machine.centerZ-p.getZ());poses.mulPose(Axis.YP.rotationDegrees(angle));double x=machine.lastPosFront+(machine.posFront-machine.lastPosFront)*partial,z=machine.lastPosLeft+(machine.posLeft-machine.lastPosLeft)*partial;poses.translate(-x,0,z);poses.mulPose(Axis.YP.rotationDegrees(machine.craneRotationOffset));poses.pushPose();poses.mulPose(Axis.YP.rotationDegrees(-machine.craneRotationOffset));int span=0;switch(machine.craneRotationOffset){case 0->{span=machine.spanF+machine.spanB+1;poses.translate(x+machine.spanB,0,0);}case 90->{span=machine.spanL+machine.spanR+1;poses.translate(0,0,-z-machine.spanR);}case 180->{span=machine.spanF+machine.spanB+1;poses.translate(x-machine.spanF,0,0);}case 270->{span=machine.spanL+machine.spanR+1;poses.translate(0,0,-z+machine.spanL);}}poses.mulPose(Axis.YP.rotationDegrees(machine.craneRotationOffset));for(int i=0;i<span;i++){crane("Girder",poses,buffers,light,overlay);poses.translate(-1,0,0);}poses.popPose();crane("Main",poses,buffers,light,overlay);poses.pushPose();for(int i=0;i<machine.height-6;i++){crane("Tube",poses,buffers,light,overlay);poses.translate(0,1,0);}poses.translate(0,-1,0);crane("Carriage",poses,buffers,light,overlay);poses.popPose();double progress=machine.lastProgress+(machine.progress-machine.lastProgress)*partial;poses.translate(0,-3.25*(1-progress),0);crane("Lift",poses,buffers,light,overlay);poses.popPose();
    }
    @Override public boolean shouldRenderOffScreen(RbmkCraneEntity machine){return true;}@Override public int getViewDistance(){return 256;}@Override public AABB getRenderBoundingBox(RbmkCraneEntity machine){return new AABB(Double.NEGATIVE_INFINITY,Double.NEGATIVE_INFINITY,Double.NEGATIVE_INFINITY,Double.POSITIVE_INFINITY,Double.POSITIVE_INFINITY,Double.POSITIVE_INFINITY);}
}
